import io.github.resilience4j.retry.Retry
import io.github.resilience4j.retry.RetryRegistry
import java.util.concurrent.atomic.AtomicInteger

class Service(private val registry: RetryRegistry) {
    private val retryField: Retry = registry.retry("svc")

    fun callService() {
        val retryCount = AtomicInteger()
        retryField.getEventPublisher().onRetry { retryCount.getAndIncrement() } // bad: lambda leaks per call
    }
}

import io.github.resilience4j.retry.Retry
import io.github.resilience4j.retry.RetryRegistry
import java.util.concurrent.atomic.AtomicInteger

class Service(private val registry: RetryRegistry) {
    private val retryField: Retry = registry.retry("svc")
    fun callAll(items: List<String>) = items.map { item ->
        val count = AtomicInteger()
        retryField.getEventPublisher().onError { count.getAndIncrement() } // bad: leaks in lambda
        item
    }
}

import io.github.resilience4j.retry.Retry
import io.github.resilience4j.retry.RetryRegistry
import java.util.concurrent.atomic.AtomicInteger

class Service(private val registry: RetryRegistry) {
    private val retryField: Retry = registry.retry("svc")
    private val retryCount = AtomicInteger()

    init {
        retryField.getEventPublisher().onRetry { retryCount.getAndIncrement() } // ok: registered once in init
    }

    fun callService() = retryField.executeCallable { "result" }
}

import io.github.resilience4j.retry.Retry
import io.github.resilience4j.retry.RetryRegistry
import java.util.concurrent.atomic.AtomicInteger

class Service(private val registry: RetryRegistry) {
    fun callService() {
        val localRetry: Retry = registry.retry("local") // local variable, not a field
        val count = AtomicInteger()
        localRetry.getEventPublisher().onRetry { count.getAndIncrement() } // ok: local retry, no persistent leak
    }
}
